<?php
if (session_status() === PHP_SESSION_NONE) { session_start(); } require_once '../includes/config.php'; require_once '../includes/database.php'; require_once '../includes/auth.php'; require_once '../includes/security/role_guard.php'; requireRole(['passenger']); $db = new Database(); $pdo = $db->getConnection(); $user_id = $_SESSION['user_id']; if ($_POST['action'] ?? '' === 'change_language') { $language = $_POST['language'] ?? ''; if (in_array($language, ['ar', 'en'])) { try { $stmt = $pdo->prepare("UPDATE users SET language = ? WHERE id = ?"); $stmt->execute([$language, $user_id]); $_SESSION['user_language'] = $language; echo json_encode(['success' => true, 'message' => 'Language changed successfully']); exit; } catch (PDOException $e) { error_log("Language change error: " . $e->getMessage()); echo json_encode(['success' => false, 'error' => 'Failed to change language']); exit; } } } try { $stmt = $pdo->prepare("SELECT language, theme FROM users WHERE id = ?"); $stmt->execute([$user_id]); $user_info = $stmt->fetch(); } catch (PDOException $e) { error_log("User info error: " . $e->getMessage()); $user_info = ['language' => 'ar', 'theme' => 'light']; } $current_language = $user_info['language'] ?? 'ar'; $current_theme = $user_info['theme'] ?? 'light'; $available_languages = [ 'ar' => [ 'name' => 'Arabic', 'native_name' => 'العربية', 'flag' => '🇸🇦', 'direction' => 'rtl' ], 'en' => [ 'name' => 'English', 'native_name' => 'English', 'flag' => '🇺🇸', 'direction' => 'ltr' ] ]; $texts = [ 'ar' => [ 'title' => 'إدارة اللغة والواجهة', 'current_language' => 'اللغة الحالية', 'select_language' => 'اختر اللغة', 'interface_settings' => 'إعدادات الواجهة', 'theme' => 'المظهر', 'light_theme' => 'فاتح', 'dark_theme' => 'داكن', 'save_changes' => 'حفظ التغييرات', 'language_changed' => 'تم تغيير اللغة بنجاح', 'theme_changed' => 'تم تغيير المظهر بنجاح', 'preview' => 'معاينة', 'back_to_dashboard' => 'العودة للوحة التحكم' ], 'en' => [ 'title' => 'Language & Interface Manager', 'current_language' => 'Current Language', 'select_language' => 'Select Language', 'interface_settings' => 'Interface Settings', 'theme' => 'Theme', 'light_theme' => 'Light', 'dark_theme' => 'Dark', 'save_changes' => 'Save Changes', 'language_changed' => 'Language changed successfully', 'theme_changed' => 'Theme changed successfully', 'preview' => 'Preview', 'back_to_dashboard' => 'Back to Dashboard' ] ]; $t = $texts[$current_language]; ?>
<!DOCTYPE html><html lang="<?php echo $current_language; ?>" dir="<?php echo $available_languages[$current_language]['direction']; ?>"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title><?php echo $t['title']; ?> - نظام تتبع الأمتعة الذكي</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><link href="https://fonts.googleapis.com/css2?family=Tajawal:wght@300;400;500;700;800&display=swap" rel="stylesheet"><script>tailwind.config={theme:{extend:{fontFamily:{tajawal:['Tajawal','sans-serif']}}}}</script><style>.rtl{direction:rtl;text-align:right}.ltr{direction:ltr;text-align:left}.theme-light{--bg-primary:#fff;--bg-secondary:#f8fafc;--text-primary:#1f2937;--text-secondary:#6b7280;--border-color:#e5e7eb}.theme-dark{--bg-primary:#1f2937;--bg-secondary:#111827;--text-primary:#f9fafb;--text-secondary:#d1d5db;--border-color:#374151}</style></head><body class="font-tajawal bg-gray-50 min-h-screen <?php echo $available_languages[$current_language]['direction']; ?>"><div class="min-h-screen flex items-center justify-center py-12 px-4 sm:px-6 lg:px-8"><div class="max-w-md w-full space-y-8"><div class="text-center"><h2 class="mt-6 text-3xl font-extrabold text-gray-900"><?php echo $t['title']; ?></h2><p class="mt-2 text-sm text-gray-600"><?php echo $t['current_language']; ?>: <?php echo $available_languages[$current_language]['flag']; ?> <?php echo $available_languages[$current_language]['native_name']; ?></p></div><div class="bg-white rounded-xl shadow-lg p-8"><div class="mb-8"><h3 class="text-lg font-semibold text-gray-900 mb-4"><i class="fas fa-globe mr-2 text-blue-600"></i><?php echo $t['select_language']; ?></h3><div class="space-y-3"><?php foreach ($available_languages as $lang_code => $lang_info): ?><label class="flex items-center p-4 border border-gray-200 rounded-lg cursor-pointer hover:bg-gray-50 transition-colors <?php echo $current_language === $lang_code ? 'border-blue-500 bg-blue-50' : ''; ?>"><input type="radio" name="language" value="<?php echo $lang_code; ?>" class="sr-only" <?php echo $current_language === $lang_code ? 'checked' : ''; ?>><div class="flex items-center"><span class="text-2xl mr-3"><?php echo $lang_info['flag']; ?></span><div><div class="font-medium text-gray-900"><?php echo $lang_info['native_name']; ?></div><div class="text-sm text-gray-500"><?php echo $lang_info['name']; ?></div></div></div><?php if ($current_language === $lang_code): ?><i class="fas fa-check-circle text-blue-600 ml-auto"></i><?php endif; ?></label><?php endforeach; ?></div></div><div class="mb-8"><h3 class="text-lg font-semibold text-gray-900 mb-4"><i class="fas fa-palette mr-2 text-purple-600"></i><?php echo $t['theme']; ?></h3><div class="grid grid-cols-2 gap-4"><label class="flex items-center p-4 border border-gray-200 rounded-lg cursor-pointer hover:bg-gray-50 transition-colors <?php echo $current_theme === 'light' ? 'border-blue-500 bg-blue-50' : ''; ?>"><input type="radio" name="theme" value="light" class="sr-only" <?php echo $current_theme === 'light' ? 'checked' : ''; ?>><div class="flex items-center"><i class="fas fa-sun text-yellow-500 mr-3"></i><div><div class="font-medium text-gray-900"><?php echo $t['light_theme']; ?></div></div></div><?php if ($current_theme === 'light'): ?><i class="fas fa-check-circle text-blue-600 ml-auto"></i><?php endif; ?></label><label class="flex items-center p-4 border border-gray-200 rounded-lg cursor-pointer hover:bg-gray-50 transition-colors <?php echo $current_theme === 'dark' ? 'border-blue-500 bg-blue-50' : ''; ?>"><input type="radio" name="theme" value="dark" class="sr-only" <?php echo $current_theme === 'dark' ? 'checked' : ''; ?>><div class="flex items-center"><i class="fas fa-moon text-indigo-500 mr-3"></i><div><div class="font-medium text-gray-900"><?php echo $t['dark_theme']; ?></div></div></div><?php if ($current_theme === 'dark'): ?><i class="fas fa-check-circle text-blue-600 ml-auto"></i><?php endif; ?></label></div></div><div class="mb-8"><h3 class="text-lg font-semibold text-gray-900 mb-4"><i class="fas fa-eye mr-2 text-green-600"></i><?php echo $t['preview']; ?></h3><div class="border border-gray-200 rounded-lg p-4 bg-gray-50"><div class="flex items-center mb-3"><div class="w-8 h-8 bg-blue-600 rounded-full flex items-center justify-center text-white text-sm font-bold mr-3">U</div><div><div class="font-medium text-gray-900"><?php echo $_SESSION['user_name']; ?></div><div class="text-sm text-gray-500">مسافر</div></div></div><div class="text-sm text-gray-600"><?php if ($current_language === 'ar'): ?>مرحباً! كيف يمكنني مساعدتك في تتبع أمتعتك؟<?php else: ?>Hello! How can I help you track your baggage?<?php endif; ?></div></div></div><div class="flex space-x-4"><button id="saveChanges" class="flex-1 bg-blue-600 text-white py-3 px-6 rounded-lg hover:bg-blue-700 transition-colors font-medium"><i class="fas fa-save mr-2"></i><?php echo $t['save_changes']; ?></button><a href="../passenger/dashboard.php" class="flex-1 bg-gray-300 text-gray-700 py-3 px-6 rounded-lg hover:bg-gray-400 transition-colors font-medium text-center"><i class="fas fa-arrow-right mr-2"></i><?php echo $t['back_to_dashboard']; ?></a></div></div></div></div><div id="toast" class="fixed top-4 right-4 bg-green-500 text-white px-6 py-3 rounded-lg shadow-lg transform translate-x-full transition-transform duration-300 z-50"><div class="flex items-center"><i class="fas fa-check-circle mr-2"></i><span id="toastMessage"></span></div></div><script>document.getElementById('saveChanges').addEventListener('click',function(){const selectedLanguage=document.querySelector('input[name="language"]:checked').value;fetch('language_manager.php',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:`action=change_language&language=${selectedLanguage}`}).then(response=>response.json()).then(data=>{if(data.success){showToast('<?php echo $t['language_changed']; ?>');setTimeout(()=>window.location.reload(),2000)}else{showToast('خطأ: '+data.error,'error')}}).catch(error=>{console.error('Error:',error);showToast('حدث خطأ في حفظ التغييرات','error')})});function showToast(message,type='success'){const toast=document.getElementById('toast');document.getElementById('toastMessage').textContent=message;toast.className=toast.className.replace(type==='error'?'bg-green-500':'bg-red-500',type==='error'?'bg-red-500':'bg-green-500');toast.classList.remove('translate-x-full');setTimeout(()=>toast.classList.add('translate-x-full'),3000)}</script></body></html>